import sys


class Fibonacci:
    def __init__(self, mod):
        self.mod = mod
        self.calculated_numbers = {0: 1, 1: 1}

    def fib(self, n):
        if n in self.calculated_numbers:
            return self.calculated_numbers[n]

        k = n // 2
        if n % 2 == 0:
            result = (self.fib(k) * self.fib(k) +
                      self.fib(k - 1) * self.fib(k - 1)) % self.mod
        else:
            result = (self.fib(k) * self.fib(k + 1) +
                      self.fib(k - 1) * self.fib(k)) % self.mod

        self.calculated_numbers[n] = result
        return result


class Exponentiation:
    @staticmethod
    def calc(a, b, m):
        if b == 0:
            return 1
        if b == 1:
            return a
        if b % 2 == 0:
            return Exponentiation.calc(a * a % m, b // 2, m)
        return a * Exponentiation.calc(a * a % m, (b - 1) // 2, m) % m


def solve():
    n, k, l, mod = map(int, sys.stdin.buffer.read().split())

    if l != 64 and (1 << l) - 1 < k:
        print(0)
        return

    zero_pos = Fibonacci(mod).fib(n + 1)
    one_pos = Exponentiation.calc(2, n, mod) - zero_pos
    while one_pos < 0:
        one_pos += mod

    result = 1
    for i in range(l):
        if k & (1 << i):
            result *= one_pos
        else:
            result *= zero_pos
        result %= mod

    print(result % mod)


if __name__ == "__main__":
    solve()

